,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P500_DISPLAY_CODE'
,p_attribute_01=>'FUNCTION_BODY'
,p_attribute_06=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'w_return varchar2(32000);',
'begin',
'    w_return := ''/* ',
'** STYLE Settings for search navigation menu and menu icons ',
'*/',
'.srch_nav span { ',
'''||CASE WHEN :P500_ICON_COLOR IS NOT NULL THEN ''   color:''||lower(:P500_ICON_COLOR)||'';',
''' ELSE '''' END||''''||CASE WHEN :P500_FONT_APEX != ''apex'' THEN ''   top:2px;',
''' ELSE '''' END||''}',
'''||CASE WHEN :P500_FONT_APEX = ''apex'' THEN ''/* FIX for navigation menu icons */',
'.t-TreeNav .a-TreeView-node--topLevel ul .a-TreeView-content .fa {',
'   vertical-align: top;',
'   width: 32px; /* This can be decrease to have smaller spacing */',
'   height: 32px;',
'   line-height: 32px;',
'   text-align: center;',
'   transition: width .2s ease;',
'}'' ELSE '''' END||''',
'''||CASE WHEN :P500_COLOR_RESAULTS=''Y'' THEN  ''/* Search resault setting */',
'.a-TreeView-label strong {',
'   font-weight:''||:P500_FONT_WEIGHT||''; ',
'''||CASE WHEN :P500_SEARCH_COLOR IS NOT NULL THEN ''   color:''||lower(:P500_SEARCH_COLOR)||'';',
''' ELSE '''' END||CASE WHEN :P500_SEARCH_BG_COLOR IS NOT NULL THEN ''   background-color:''||lower(:P500_SEARCH_BG_COLOR)||'';',
''' ELSE '''' END',
'||''}',
''' ELSE '''' END||CASE WHEN :P500_COLOR_BOX=''Y'' THEN CASE WHEN :P500_BOX_COLOR IS NOT NULL OR :P500_BOX_BG_COLOR IS NOT NULL OR :P500_BOX_BORDER IS NOT NULL THEN''/* Input field style setting */',
'.srch_nav input {',
'''||CASE WHEN :P500_BOX_COLOR IS NOT NULL THEN ''   color:''||lower(:P500_BOX_COLOR)||'';',
''' ELSE '''' END||CASE WHEN :P500_BOX_BG_COLOR IS NOT NULL THEN ''   background-color:''||lower(:P500_BOX_BG_COLOR)||'';',
''' ELSE '''' END||CASE WHEN :P500_BOX_BORDER IS NOT NULL THEN ''   border-color:''||lower(:P500_BOX_BORDER)||'';',
''' ELSE '''' END||''}'' ELSE '''' END||CASE WHEN lower(:P500_BOX_BORDER_HOVER) IS NOT NULL THEN ''',
'/* Input field on hover setting */',
'.srch_nav input:focus {',
'    border-color:''||lower(:P500_BOX_BORDER_HOVER)||'';',
'}'' ELSE '''' END ELSE '''' END;',
'',
'return w_return;',
'end;'))
