begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(914275876010718703)
,p_install_id=>wwv_flow_imp.id(914273253811715699)
,p_name=>'install SNM tables'
,p_sequence=>10
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'CREATE TABLE SNM_DEPT(DEPTNO NUMBER PRIMARY KEY,',
'                      DNAME VARCHAR2(30),',
'					  LOC   VARCHAR2(60));',
'INSERT INTO SNM_DEPT(DEPTNO, DNAME, LOC) VALUES(10, ''ACCOUNTING'', ''Slovenia - MARIBOR'');',
'INSERT INTO SNM_DEPT(DEPTNO, DNAME, LOC) VALUES(20, ''RESEARCH'', ''Slovenia - LJUBLJANA'');',
'INSERT INTO SNM_DEPT(DEPTNO, DNAME, LOC) VALUES(30, ''SALES'', ''Slovenia - LJUBLJANA'');',
'INSERT INTO SNM_DEPT(DEPTNO, DNAME, LOC) VALUES(40, ''OPERATIONS'', ''Slovenia - LJUBLJANA'');',
'INSERT INTO SNM_DEPT(DEPTNO, DNAME, LOC) VALUES(50, ''IT'', ''Slovenia - LJUBLJANA'');',
'	',
'COMMIT;	',
'					   ',
'CREATE TABLE SNM_EMP(EMPNO NUMBER PRIMARY KEY,',
'                     ENAME VARCHAR2(30),',
'					 DEPTNO NUMBER REFERENCES  SNM_DEPT(DEPTNO),',
'					 JOB VARCHAR2(30),',
'					 HIREDATE DATE,',
'					 COMPANY VARCHAR2(60),',
'					 SAL NUMBER,',
'					 ACTIVE VARCHAR2(1) DEFAULT ''Y'');',
'',
'INSERT INTO SNM_EMP(EMPNO, ENAME, DEPTNO, JOB, HIREDATE, COMPANY, SAL) VALUES (8020,''ANDREJ GRLICA'',50,''APEX DEVELOPER'',to_date(''01/07/2017'',''DD/MM/YYYY''),''The RIGHT THING Solutions'',3000);					  ',
